  input [3:0] alu_control;
  input regwrite, clock, reset, DFT_sdi, DFT_sen;
  output zero_flag, DFT_sdo;
  wire [4:0] read_reg_num1, read_reg_num2, write_reg;
  wire [3:0] alu_control;
  wire regwrite, clock, reset, DFT_sdi, DFT_sen;
  wire zero_flag, DFT_sdo;
  wire [31:0] read_data1;
  wire [31:0] read_data2;
  wire [31:0] write_data;
  ALU alu_module(read_data1, read_data2, {1'b0, alu_control[2:0]},
       write_data, zero_flag);
  REG_FILE reg_file_module(5'b00000, {read_reg_num2[4:1], 1'b1},
       write_reg, write_data, read_data1, read_data2, 1'b1, clock,
       1'b0, DFT_sdi, DFT_sen, DFT_sdo);
endmodule

